while let s = readLine() {
    let s = Array(s)
    print(
        String(
            Dictionary(grouping: s, by: { $0 })
                .sorted {
                    let a = $0.value.count
                    let b = $1.value.count
                    return a == b ? s.index(of: $0.key)! < s.index(of: $1.key)! : a > b
                }.map {
                    $0.key
                }
        )
    )
}
